using FluNET.Prompt;using FluNET.Prompt.Surface;namespace FluNET.Compilation.Lowering;internal static class SurfaceDataLowering
{
 public static bool IsDataStage(SurfaceCommandSyntax c)=>c.NormalizedName is"FILTER"or"SORT"or"TAKE"or"SELECT"or"MAP"or"DEFAULT"or"FOREACH"or"GROUP"or"SUM"or"JOIN"or"MATCH";
 public static bool HasExplicitInput(SurfaceCommandSyntax c){if(c.NormalizedName is"JOIN"or"MATCH")return true;if(c.NormalizedName!="FOREACH"||c.Values.Count!=1)return false;try{return SurfaceForEachDescriptor.Decode(c.Values[0].UnquotedText).SourceName is not null;}catch{return false;}}
 public static CommandSyntax?Lower(SurfaceCommandSyntax s,string input,string output,PromptGrammar g,ICollection<SurfaceDiagnostic>d)=>s.NormalizedName switch{"FILTER"=>Filter(s,input,output,g,d),"SORT"=>Sort(s,input,output,g,d),"TAKE"=>Take(s,input,output,g,d),"SELECT"=>Select(s,input,output,g,d),"MAP"=>Map(s,input,output,g,d),"DEFAULT"=>Default(s,input,output,g,d),"FOREACH"=>ForEach(s,input,output,g,d),"GROUP"=>Group(s,input,output,g,d),"SUM"=>Sum(s,input,output,g,d),"JOIN"=>Join(s,input,output,g,d),"MATCH"=>Match(s,input,output,g,d),_=>null};
 private static CommandSyntax?Filter(SurfaceCommandSyntax s,string i,string o,PromptGrammar g,ICollection<SurfaceDiagnostic>d){if(s.Values.Count!=1||string.IsNullOrWhiteSpace(s.Values[0].UnquotedText)){d.Add(new("FLN260","FILTER requires one predicate expression.",s.Span));return null;}return Cmd("FILTERJSON",o,i,s.Values[0].UnquotedText,s.Values[0],g);}private static CommandSyntax?Sort(SurfaceCommandSyntax s,string i,string o,PromptGrammar g,ICollection<SurfaceDiagnostic>d){if(s.Values.Count!=1||!s.Values[0].UnquotedText.Trim().StartsWith("BY ",StringComparison.OrdinalIgnoreCase)){d.Add(new("FLN261","SORT requires `BY expression`.",s.Span));return null;}return Cmd("SORTJSON",o,i,s.Values[0].UnquotedText.Trim()[3..].Trim(),s.Values[0],g);}private static CommandSyntax?Take(SurfaceCommandSyntax s,string i,string o,PromptGrammar g,ICollection<SurfaceDiagnostic>d){if(s.Values.Count!=1||!int.TryParse(s.Values[0].UnquotedText,out int n)||n<0){d.Add(new("FLN262","TAKE requires one non-negative integer.",s.Span));return null;}return Cmd("TAKEJSON",o,i,n.ToString(),s.Values[0],g);}private static CommandSyntax?Select(SurfaceCommandSyntax s,string i,string o,PromptGrammar g,ICollection<SurfaceDiagnostic>d){if(s.Values.Count==0){d.Add(new("FLN264","SELECT requires fields.",s.Span));return null;}return Cmd("PROJECTJSON",o,i,$"select:{string.Join(", ",s.Values.Select(v=>v.UnquotedText.Trim()))}",s.Values[0],g);}private static CommandSyntax?Map(SurfaceCommandSyntax s,string i,string o,PromptGrammar g,ICollection<SurfaceDiagnostic>d){if(s.Values.Count!=1||!s.Values[0].UnquotedText.Trim().StartsWith("TO ",StringComparison.OrdinalIgnoreCase)){d.Add(new("FLN265","MAP requires `TO {...}`.",s.Span));return null;}return Cmd("PROJECTJSON",o,i,$"map:{s.Values[0].UnquotedText.Trim()[3..].Trim()}",s.Values[0],g);}private static CommandSyntax?Default(SurfaceCommandSyntax s,string i,string o,PromptGrammar g,ICollection<SurfaceDiagnostic>d){if(s.Values.Count!=1){d.Add(new("FLN266","DEFAULT requires `field TO fallback`.",s.Span));return null;}string t=s.Values[0].UnquotedText;int x=t.IndexOf(" TO ",StringComparison.OrdinalIgnoreCase);if(x<=0){d.Add(new("FLN266","DEFAULT requires `field TO fallback`.",s.Span));return null;}return Cmd("DEFAULTJSON",o,i,$"{t[..x].Trim()}|{t[(x+4)..].Trim()}",s.Values[0],g);}
 private static CommandSyntax?ForEach(SurfaceCommandSyntax s,string input,string o,PromptGrammar g,ICollection<SurfaceDiagnostic>d){if(s.Values.Count!=1){d.Add(new("FLN275","FOREACH requires descriptor.",s.Span));return null;}SurfaceForEachDescriptor descriptor;try{descriptor=SurfaceForEachDescriptor.Decode(s.Values[0].UnquotedText);}catch(FormatException e){d.Add(new("FLN275",e.Message,s.Span));return null;}string actual=descriptor.SourceName??input;if(string.IsNullOrWhiteSpace(actual)){d.Add(new("FLN263","FOR EACH requires a previous data value or explicit IN collection.",s.Span));return null;}return Cmd("FOREACHJSON",o,Norm(actual),s.Values[0].UnquotedText,s.Values[0],g);}
 private static CommandSyntax?Group(SurfaceCommandSyntax s,string i,string o,PromptGrammar g,ICollection<SurfaceDiagnostic>d){if(s.Values.Count!=1){d.Add(new("FLN280","GROUP requires BY expression.",s.Span));return null;}string t=s.Values[0].UnquotedText.Trim();string actual=i;string key;if(t.StartsWith("BY ",StringComparison.OrdinalIgnoreCase))key=t[3..].Trim();else{int by=t.IndexOf(" BY ",StringComparison.OrdinalIgnoreCase);if(by<=0){d.Add(new("FLN280","GROUP requires BY expression.",s.Span));return null;}actual=Norm(t[..by]);key=t[(by+4)..].Trim();}return Cmd("GROUPJSON",o,actual,key,s.Values[0],g);}private static CommandSyntax?Sum(SurfaceCommandSyntax s,string i,string o,PromptGrammar g,ICollection<SurfaceDiagnostic>d){if(s.Values.Count!=1){d.Add(new("FLN281","SUM requires expression.",s.Span));return null;}return Cmd("SUMJSON",o,i,s.Values[0].UnquotedText.Trim(),s.Values[0],g);}private static CommandSyntax?Join(SurfaceCommandSyntax s,string i,string o,PromptGrammar g,ICollection<SurfaceDiagnostic>d){if(s.Values.Count!=1){d.Add(new("FLN282","JOIN requires left WITH right ON left.key = right.key.",s.Span));return null;}string t=s.Values[0].UnquotedText;int w=t.IndexOf(" WITH ",StringComparison.OrdinalIgnoreCase),on=t.IndexOf(" ON ",StringComparison.OrdinalIgnoreCase);if(w<=0||on<=w+6){d.Add(new("FLN282","Invalid JOIN.",s.Span));return null;}string l=Norm(t[..w]),r=Norm(t[(w+6)..on]);string condition=t[(on+4)..];if(!Keys(condition,l,r,out string?lk,out string?rk)){d.Add(new("FLN282","Invalid JOIN keys.",s.Span));return null;}return JoinCmd(o,l,r,lk!,rk!,s.Values[0],g);}private static CommandSyntax?Match(SurfaceCommandSyntax s,string i,string o,PromptGrammar g,ICollection<SurfaceDiagnostic>d){if(s.Values.Count!=1){d.Add(new("FLN283","MATCH requires left.key TO right.key.",s.Span));return null;}string t=s.Values[0].UnquotedText;int to=t.IndexOf(" TO ",StringComparison.OrdinalIgnoreCase);if(to<=0||!Root(t[..to],out string?l,out string?lk)||!Root(t[(to+4)..],out string?r,out string?rk)){d.Add(new("FLN283","Invalid MATCH.",s.Span));return null;}return JoinCmd(o,l!,r!,lk!,rk!,s.Values[0],g);}
 private static bool Keys(string c,string l,string r,out string?lk,out string?rk){lk=rk=null;int e=c.IndexOf("==",StringComparison.Ordinal),w=2;if(e<0){e=c.IndexOf('=');w=1;}if(e<=0)return false;string a=c[..e].Trim(),b=c[(e+w)..].Trim();return Strip(a,l,out lk)&&Strip(b,r,out rk)||Strip(b,l,out lk)&&Strip(a,r,out rk);}private static bool Root(string p,out string?root,out string?key){int dot=p.IndexOf('.');if(dot<=0){root=key=null;return false;}root=Norm(p[..dot]);key=p[(dot+1)..].Trim();return key.Length>0;}private static bool Strip(string p,string r,out string?key){string prefix=r+".";if(!p.StartsWith(prefix,StringComparison.OrdinalIgnoreCase)){key=null;return false;}key=p[prefix.Length..].Trim();return key.Length>0;}private static string Norm(string v)=>v.Trim().TrimStart('[').TrimEnd(']');
 private static CommandSyntax JoinCmd(string o,string l,string r,string lk,string rk,SurfaceValueSyntax s,PromptGrammar g)=>new([T("JOINJSON",PromptTokenKind.Word,s.Span.Start),T($"[{o}]",PromptTokenKind.Variable,s.Span.Start),T("FROM",PromptTokenKind.Word,s.Span.Start),T($"[{l}]",PromptTokenKind.Variable,s.Span.Start),T("TO",PromptTokenKind.Word,s.Span.Start),T($"[{r}]",PromptTokenKind.Variable,s.Span.Start),T("USING",PromptTokenKind.Word,s.Span.Start),T($"{{{lk}|{rk}}}",PromptTokenKind.Reference,s.Span.Start)],g);private static CommandSyntax Cmd(string v,string o,string i,string value,SurfaceValueSyntax s,PromptGrammar g)=>new([T(v,PromptTokenKind.Word,s.Span.Start),T($"[{o}]",PromptTokenKind.Variable,s.Span.Start),T("FROM",PromptTokenKind.Word,s.Span.Start),T($"[{i}]",PromptTokenKind.Variable,s.Span.Start),T("USING",PromptTokenKind.Word,s.Span.Start),T($"{{{value}}}",PromptTokenKind.Reference,s.Span.Start)],g);private static PromptToken T(string x,PromptTokenKind k,int s)=>new(x,k,Math.Max(0,s),0);
}
